<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time</title>

    <!-- Fonts: Bricolage Grotesque (display) + Nunito Sans (body) from Google Fonts -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,700;12..96,800&family=Nunito+Sans:opsz,wght@6..12,400;6..12,500;6..12,600;6..12,700&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Data-forward, authoritative, accessible
           =========================================== */
        :root {
            /* Colors — deep slate with medical/teal accents */
            --bg-primary: #0b1220;
            --bg-secondary: #111d2e;
            --bg-card: #162236;
            --bg-card-hover: #1a2a42;
            --text-primary: #edf2f7;
            --text-secondary: #94a3b8;
            --text-muted: #64748b;
            --accent-teal: #0ea5e9;
            --accent-teal-glow: rgba(14, 165, 233, 0.25);
            --accent-green: #10b981;
            --accent-green-glow: rgba(16, 185, 129, 0.2);
            --accent-amber: #f59e0b;
            --accent-amber-glow: rgba(245, 158, 11, 0.2);
            --accent-red: #ef4444;
            --accent-red-glow: rgba(239, 68, 68, 0.2);
            --accent-coral: #f97316;
            --border-subtle: rgba(148, 163, 184, 0.12);
            --border-accent: rgba(14, 165, 233, 0.3);

            /* Typography — MUST use clamp() */
            --font-display: 'Bricolage Grotesque', sans-serif;
            --font-body: 'Nunito Sans', sans-serif;
            --title-size: clamp(1.5rem, 5vw, 4rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1rem, 2.5vw, 1.75rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --label-size: clamp(0.55rem, 0.8vw, 0.75rem);

            /* Spacing — MUST use clamp() */
            --slide-padding: clamp(1rem, 4vw, 4rem);
            --content-gap: clamp(0.5rem, 2vw, 2rem);
            --element-gap: clamp(0.25rem, 1vw, 1rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
            --duration-normal: 0.6s;
            --duration-slow: 1s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */

        /* 1. Lock html/body to viewport */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        /* 2. Each slide = exact viewport height */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            background: var(--bg-primary);
        }

        /* 3. Content container with flex for centering */
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* 4. ALL typography uses clamp() for responsive scaling */
        :root {
            --title-size: clamp(1.5rem, 5vw, 4rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1rem, 2.5vw, 1.75rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --slide-padding: clamp(1rem, 4vw, 4rem);
            --content-gap: clamp(0.5rem, 2vw, 2rem);
            --element-gap: clamp(0.25rem, 1vw, 1rem);
        }

        /* 5. Cards/containers use viewport-relative max sizes */
        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        /* 6. Lists auto-scale with viewport */
        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }

        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }

        /* 7. Grids adapt to available space */
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        /* 8. Images constrained to viewport */
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* ===========================================
           RESPONSIVE BREAKPOINTS
           =========================================== */

        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }

        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }

        /* ===========================================
           REDUCED MOTION
           =========================================== */
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           GLOBAL TYPOGRAPHY
           =========================================== */
        body {
            font-family: var(--font-body);
            color: var(--text-primary);
            background: var(--bg-primary);
            -webkit-font-smoothing: antialiased;
        }

        h1, h2, h3 {
            font-family: var(--font-display);
            line-height: 1.15;
            letter-spacing: -0.02em;
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.92);
            transition: opacity 0.8s var(--ease-out-expo),
                        transform 0.8s var(--ease-out-expo);
        }

        .slide.visible .reveal-scale {
            opacity: 1;
            transform: scale(1);
        }

        .reveal-left {
            opacity: 0;
            transform: translateX(-40px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal-left {
            opacity: 1;
            transform: translateX(0);
        }

        /* Stagger for child elements within a reveal container */
        .stagger-children > * {
            opacity: 0;
            transform: translateY(15px);
            transition: opacity 0.5s var(--ease-out-expo),
                        transform 0.5s var(--ease-out-expo);
        }

        .slide.visible .stagger-children > *:nth-child(1) { transition-delay: 0.1s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(2) { transition-delay: 0.2s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(3) { transition-delay: 0.3s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(4) { transition-delay: 0.4s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(5) { transition-delay: 0.5s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(6) { transition-delay: 0.6s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(7) { transition-delay: 0.7s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(8) { transition-delay: 0.8s; opacity: 1; transform: translateY(0); }
        .slide.visible .stagger-children > *:nth-child(9) { transition-delay: 0.9s; opacity: 1; transform: translateY(0); }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-teal), var(--accent-green));
            z-index: 9999;
            transition: width 0.3s ease;
        }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 1.5vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(6px, 1vh, 12px);
            z-index: 9998;
        }

        .nav-dot {
            width: clamp(6px, 0.6vw, 10px);
            height: clamp(6px, 0.6vw, 10px);
            border-radius: 50%;
            background: rgba(148, 163, 184, 0.3);
            border: none;
            cursor: pointer;
            transition: all 0.3s ease;
            padding: 0;
        }

        .nav-dot.active {
            background: var(--accent-teal);
            box-shadow: 0 0 8px var(--accent-teal-glow);
            transform: scale(1.3);
        }

        .nav-dot:hover {
            background: rgba(148, 163, 184, 0.6);
        }

        /* ===========================================
           SLIDE NUMBER INDICATOR
           =========================================== */
        .slide-number {
            position: absolute;
            top: clamp(0.75rem, 2vh, 1.5rem);
            left: clamp(1rem, 3vw, 3rem);
            font-family: var(--font-display);
            font-size: var(--label-size);
            color: var(--text-muted);
            letter-spacing: 0.15em;
            text-transform: uppercase;
        }

        /* ===========================================
           BACKGROUND EFFECTS
           =========================================== */
        .gradient-bg {
            background:
                radial-gradient(ellipse at 15% 85%, rgba(14, 165, 233, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 85% 15%, rgba(16, 185, 129, 0.06) 0%, transparent 50%),
                var(--bg-primary);
        }

        .grid-bg {
            background-image:
                linear-gradient(rgba(148, 163, 184, 0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(148, 163, 184, 0.03) 1px, transparent 1px);
            background-size: 60px 60px;
        }

        /* ===========================================
           SLIDE 1: TITLE SLIDE
           =========================================== */
        .title-slide {
            background:
                radial-gradient(ellipse at 30% 70%, rgba(14, 165, 233, 0.1) 0%, transparent 60%),
                radial-gradient(ellipse at 70% 30%, rgba(16, 185, 129, 0.07) 0%, transparent 50%),
                var(--bg-primary);
            justify-content: center;
            align-items: center;
            text-align: center;
        }

        .title-slide .slide-content {
            justify-content: center;
            align-items: center;
            text-align: center;
        }

        .title-main {
            font-size: clamp(1.8rem, 4.5vw, 3.5rem);
            font-weight: 800;
            max-width: min(85vw, 900px);
            margin-bottom: clamp(0.5rem, 1.5vw, 1.5rem);
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-teal) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .title-subtitle {
            font-family: var(--font-body);
            font-size: clamp(0.85rem, 1.8vw, 1.35rem);
            color: var(--text-secondary);
            max-width: min(70vw, 650px);
            line-height: 1.5;
            margin-bottom: clamp(1rem, 3vh, 2.5rem);
        }

        .title-meta {
            display: flex;
            gap: clamp(1rem, 3vw, 2rem);
            font-size: var(--small-size);
            color: var(--text-muted);
            flex-wrap: wrap;
            justify-content: center;
        }

        .title-meta span {
            display: flex;
            align-items: center;
            gap: 0.4em;
        }

        .title-divider {
            width: min(200px, 30vw);
            height: 2px;
            background: linear-gradient(90deg, transparent, var(--accent-teal), transparent);
            margin-bottom: clamp(0.5rem, 1.5vh, 1.5rem);
        }

        /* ===========================================
           SLIDE 2: VACCINE TIMELINE
           =========================================== */
        .bar-chart-container {
            display: flex;
            flex-direction: column;
            gap: clamp(0.25rem, 0.5vh, 0.5rem);
            width: 100%;
            max-height: min(60vh, 480px);
        }

        .bar-row {
            display: grid;
            grid-template-columns: clamp(70px, 10vw, 130px) 1fr clamp(35px, 4vw, 55px);
            align-items: center;
            gap: clamp(0.3rem, 0.8vw, 0.8rem);
        }

        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
            white-space: nowrap;
            font-weight: 500;
        }

        .bar-track {
            height: clamp(14px, 2vh, 24px);
            background: var(--bg-card);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1.2s var(--ease-out-expo);
            position: relative;
        }

        .bar-fill.standard {
            background: linear-gradient(90deg, var(--accent-teal), rgba(14, 165, 233, 0.6));
        }

        .bar-fill.covid {
            background: linear-gradient(90deg, var(--accent-coral), var(--accent-amber));
            box-shadow: 0 0 12px var(--accent-amber-glow);
        }

        .bar-value {
            font-size: var(--small-size);
            font-weight: 700;
            color: var(--text-primary);
            white-space: nowrap;
        }

        .bar-value.covid-value {
            color: var(--accent-amber);
        }

        .covid-highlight {
            border: 1px solid var(--accent-amber);
            background: rgba(245, 158, 11, 0.05);
            border-radius: 6px;
            padding: clamp(0.15rem, 0.3vw, 0.35rem) clamp(0.3rem, 0.5vw, 0.6rem);
        }

        /* ===========================================
           SLIDE 3: DISEASE ELIMINATION TABLE
           =========================================== */
        .data-table-wrapper {
            overflow: hidden;
            width: 100%;
        }

        .data-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--small-size);
        }

        .data-table thead th {
            background: var(--bg-card);
            color: var(--accent-teal);
            font-weight: 600;
            padding: clamp(0.3rem, 0.6vh, 0.6rem) clamp(0.4rem, 0.8vw, 0.8rem);
            text-align: left;
            border-bottom: 2px solid var(--border-accent);
            font-size: var(--label-size);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            white-space: nowrap;
        }

        .data-table tbody td {
            padding: clamp(0.25rem, 0.5vh, 0.5rem) clamp(0.4rem, 0.8vw, 0.8rem);
            border-bottom: 1px solid var(--border-subtle);
            color: var(--text-secondary);
            white-space: nowrap;
        }

        .data-table tbody tr:hover {
            background: rgba(14, 165, 233, 0.04);
        }

        .eliminated {
            color: var(--accent-green);
            font-weight: 700;
        }

        .partial {
            color: var(--accent-amber);
            font-weight: 600;
        }

        .disease-name {
            color: var(--text-primary);
            font-weight: 600;
        }

        /* ===========================================
           SLIDE 4: MEASLES HEATMAP
           =========================================== */
        .heatmap-container {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }

        .heatmap-row {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.5vw, 0.5rem);
        }

        .heatmap-year-label {
            font-size: var(--label-size);
            color: var(--text-muted);
            width: clamp(30px, 4vw, 45px);
            text-align: right;
            flex-shrink: 0;
        }

        .heatmap-cells {
            display: flex;
            gap: 1px;
            flex: 1;
        }

        .heatmap-cell {
            flex: 1;
            height: clamp(8px, 1.2vh, 14px);
            border-radius: 2px;
            min-width: 0;
        }

        .heatmap-legend {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.5vw, 0.5rem);
            font-size: var(--label-size);
            color: var(--text-muted);
            justify-content: center;
            flex-wrap: wrap;
        }

        .legend-swatch {
            width: clamp(16px, 2vw, 28px);
            height: clamp(8px, 1vh, 12px);
            border-radius: 2px;
            display: inline-block;
        }

        .milestone-markers {
            display: flex;
            justify-content: center;
            gap: clamp(1rem, 3vw, 3rem);
            flex-wrap: wrap;
        }

        .milestone {
            display: flex;
            align-items: center;
            gap: 0.4em;
            font-size: var(--small-size);
            font-weight: 600;
        }

        .milestone-dot {
            width: clamp(6px, 0.6vw, 10px);
            height: clamp(6px, 0.6vw, 10px);
            border-radius: 50%;
            flex-shrink: 0;
        }

        /* ===========================================
           SLIDE 5: SMALLPOX ERADICATION
           =========================================== */
        .timeline-container {
            display: flex;
            flex-direction: column;
            gap: 0;
            position: relative;
            padding-left: clamp(1.5rem, 3vw, 2.5rem);
        }

        .timeline-container::before {
            content: '';
            position: absolute;
            left: clamp(0.5rem, 1.2vw, 0.9rem);
            top: 0;
            bottom: 0;
            width: 2px;
            background: linear-gradient(180deg, var(--accent-teal), var(--accent-green), var(--accent-amber));
        }

        .timeline-item {
            position: relative;
            padding-bottom: clamp(0.5rem, 1.5vh, 1.2rem);
        }

        .timeline-item::before {
            content: '';
            position: absolute;
            left: calc(-1 * clamp(1.5rem, 3vw, 2.5rem) + clamp(0.35rem, 0.9vw, 0.7rem));
            top: clamp(0.2rem, 0.5vh, 0.5rem);
            width: clamp(8px, 0.8vw, 12px);
            height: clamp(8px, 0.8vw, 12px);
            border-radius: 50%;
            background: var(--accent-teal);
            border: 2px solid var(--bg-primary);
        }

        .timeline-year {
            font-family: var(--font-display);
            font-size: clamp(0.85rem, 1.5vw, 1.15rem);
            color: var(--accent-teal);
            font-weight: 700;
        }

        .timeline-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .eradication-factors {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
            gap: clamp(0.4rem, 1vw, 0.8rem);
            margin-top: clamp(0.5rem, 1vh, 1rem);
        }

        .factor-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.4rem, 1vh, 0.8rem) clamp(0.5rem, 1vw, 1rem);
            text-align: center;
        }

        .factor-card .factor-icon {
            font-size: clamp(1rem, 1.8vw, 1.5rem);
            margin-bottom: 0.2em;
        }

        .factor-card .factor-text {
            font-size: var(--label-size);
            color: var(--text-secondary);
            line-height: 1.3;
        }

        /* ===========================================
           SLIDE 6: HERD IMMUNITY
           =========================================== */
        .herd-diagram {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: clamp(1.5rem, 4vw, 3rem);
            flex-wrap: wrap;
        }

        .herd-visual {
            position: relative;
            width: clamp(180px, 30vw, 320px);
            height: clamp(180px, 30vw, 320px);
            flex-shrink: 0;
        }

        .herd-visual svg {
            width: 100%;
            height: 100%;
        }

        .herd-explanation {
            max-width: min(450px, 45vw);
        }

        .herd-explanation h3 {
            font-size: clamp(0.95rem, 1.8vw, 1.35rem);
            color: var(--text-primary);
            margin-bottom: clamp(0.3rem, 0.8vh, 0.8rem);
        }

        .herd-point {
            display: flex;
            align-items: flex-start;
            gap: 0.5em;
            margin-bottom: clamp(0.3rem, 0.6vh, 0.6rem);
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .herd-point .point-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            flex-shrink: 0;
            margin-top: 0.35em;
        }

        /* ===========================================
           SLIDE 7: REMAINING CHALLENGES
           =========================================== */
        .challenge-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        .challenge-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 10px;
            padding: clamp(0.6rem, 1.5vh, 1.2rem) clamp(0.8rem, 1.5vw, 1.5rem);
            position: relative;
            overflow: hidden;
        }

        .challenge-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
        }

        .challenge-card.red::before { background: var(--accent-red); }
        .challenge-card.amber::before { background: var(--accent-amber); }
        .challenge-card.teal::before { background: var(--accent-teal); }

        .challenge-disease {
            font-family: var(--font-display);
            font-size: clamp(0.8rem, 1.4vw, 1.05rem);
            color: var(--text-primary);
            font-weight: 700;
            margin-bottom: clamp(0.2rem, 0.5vh, 0.5rem);
        }

        .challenge-stat {
            font-size: clamp(1.2rem, 2.5vw, 2rem);
            font-family: var(--font-display);
            font-weight: 800;
            margin-bottom: 0.1em;
        }

        .challenge-stat.red { color: var(--accent-red); }
        .challenge-stat.amber { color: var(--accent-amber); }
        .challenge-stat.teal { color: var(--accent-teal); }

        .challenge-label {
            font-size: var(--label-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.08em;
        }

        .barrier-list {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.6vh, 0.5rem);
        }

        .barrier-item {
            display: flex;
            align-items: flex-start;
            gap: 0.5em;
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.35;
        }

        .barrier-icon {
            font-size: clamp(0.8rem, 1.2vw, 1rem);
            flex-shrink: 0;
            margin-top: 0.1em;
        }

        /* ===========================================
           SLIDE 8: TAKEAWAYS
           =========================================== */
        .takeaway-list {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 0.8rem);
        }

        .takeaway-item {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.5rem, 1vw, 1rem);
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.4rem, 1vh, 0.8rem) clamp(0.6rem, 1.2vw, 1.2rem);
        }

        .takeaway-number {
            font-family: var(--font-display);
            font-size: clamp(1rem, 2vw, 1.5rem);
            font-weight: 800;
            color: var(--accent-teal);
            flex-shrink: 0;
            line-height: 1;
        }

        .takeaway-text {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .takeaway-text strong {
            color: var(--text-primary);
        }

        .call-to-action {
            background: linear-gradient(135deg, rgba(14, 165, 233, 0.1), rgba(16, 185, 129, 0.08));
            border: 1px solid var(--border-accent);
            border-radius: 10px;
            padding: clamp(0.6rem, 1.5vh, 1.2rem) clamp(1rem, 2vw, 2rem);
            text-align: center;
            margin-top: clamp(0.4rem, 1vh, 0.8rem);
        }

        .cta-text {
            font-family: var(--font-display);
            font-size: clamp(0.8rem, 1.5vw, 1.1rem);
            color: var(--accent-teal);
            font-weight: 700;
        }

        .cta-subtext {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.3em;
        }

        /* ===========================================
           UTILITY CLASSES
           =========================================== */
        .text-accent { color: var(--accent-teal); }
        .text-green { color: var(--accent-green); }
        .text-amber { color: var(--accent-amber); }
        .text-red { color: var(--accent-red); }
        .text-muted { color: var(--text-muted); }
        .text-secondary { color: var(--text-secondary); }

        .slide-header {
            margin-bottom: clamp(0.5rem, 1.5vh, 1.5rem);
        }

        .slide-title {
            font-size: clamp(1rem, 2.5vw, 1.75rem);
            font-weight: 800;
            color: var(--text-primary);
            margin-bottom: clamp(0.2rem, 0.5vh, 0.5rem);
        }

        .slide-subtitle {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .badge {
            display: inline-flex;
            align-items: center;
            gap: 0.3em;
            padding: 0.15em 0.6em;
            border-radius: 4px;
            font-size: var(--label-size);
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.06em;
        }

        .badge-green { background: var(--accent-green-glow); color: var(--accent-green); }
        .badge-amber { background: var(--accent-amber-glow); color: var(--accent-amber); }
