    });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto(process.env.TARGET_URL, { waitUntil: 'networkidle' });

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log('Found ' + slideCount + ' slides');

    // Capture each slide by scrolling it into view
    for (let i = 0; i < slideCount; i++) {
        // Scroll the slide into view using JS
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                slides[idx].scrollIntoView({ behavior: 'instant' });
            }
        }, i);

        // Wait for animations to trigger (IntersectionObserver)
        await page.waitForTimeout(800);

        // Force .visible class on the slide and its children
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                slides[idx].classList.add('visible');
            }
        }, i);

        // Small delay for CSS transitions
        await page.waitForTimeout(400);

        // Take screenshot of the viewport
        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({ path: process.env.OUT_DIR + '/slide_' + idx + '.png' });
        console.log('Captured slide ' + (i + 1));
    }

    console.log(JSON.stringify({ captured: slideCount }));
    await browser.close();
})();
