#!/usr/bin/env python3
"""Custom capture script: uses Playwright to scroll to each .slide element
and take a screenshot, then assembles into a 16:9 PPTX."""

import http.server
import json
import os
import subprocess
import sys
import tempfile
import threading
from pathlib import Path

from PIL import Image
from pptx import Presentation
from pptx.util import Emu


CAPTURE_SCRIPT = r"""
const { chromium } = require('playwright');

(async () => {
    const browser = await chromium.launch({
        executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined
    });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto(process.env.TARGET_URL, { waitUntil: 'networkidle' });

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log('Found ' + slideCount + ' slides');

    // Capture each slide by scrolling it into view
    for (let i = 0; i < slideCount; i++) {
        // Scroll the slide into view using JS
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                slides[idx].scrollIntoView({ behavior: 'instant' });
            }
        }, i);

        // Wait for animations to trigger (IntersectionObserver)
        await page.waitForTimeout(800);

        // Force .visible class on the slide and its children
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {
                slides[idx].classList.add('visible');
            }
        }, i);

        // Small delay for CSS transitions
        await page.waitForTimeout(400);

        // Take screenshot of the viewport
        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({ path: process.env.OUT_DIR + '/slide_' + idx + '.png' });
        console.log('Captured slide ' + (i + 1));
    }

    console.log(JSON.stringify({ captured: slideCount }));
    await browser.close();
})();
"""


def start_http_server(directory, port=0):
    handler = http.server.SimpleHTTPRequestHandler
    server = http.server.HTTPServer(
        ("127.0.0.1", port),
        lambda *a, **kw: handler(*a, directory=str(directory), **kw),
    )
    actual_port = server.server_address[1]
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return server, actual_port


def main():
    html_path = Path("/app/output/presentation.html").resolve()
    output_path = Path("/app/output/final_deck.pptx").resolve()

    serve_dir = html_path.parent
    server, port = start_http_server(serve_dir)
    url = f"http://127.0.0.1:{port}/{html_path.name}"

    with tempfile.TemporaryDirectory(prefix="slides_") as tmp:
        tmp_dir = Path(tmp)

        # Write capture script
        script_file = tmp_dir / "_capture.cjs"
        script_file.write_text(CAPTURE_SCRIPT)

        env = os.environ.copy()
        env["TARGET_URL"] = url
        env["OUT_DIR"] = str(tmp_dir)
        env.setdefault("NODE_PATH", "/usr/local/lib/node_modules:/app/node_modules")
        env.setdefault("PLAYWRIGHT_BROWSERS_PATH", "/root/.cache/ms-playwright")
        env.setdefault("PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH", "/root/.cache/ms-playwright/chromium-1223/chrome-linux64/chrome")

        print(f"Capturing slides from {url} ...")
        result = subprocess.run(
            ["node", str(script_file)],
            capture_output=True,
            text=True,
            timeout=180,
            env=env,
        )

        if result.returncode != 0:
            print(f"Stdout: {result.stdout}", file=sys.stderr)
            print(f"Stderr: {result.stderr}", file=sys.stderr)
            raise RuntimeError(f"Capture failed (exit {result.returncode})")

        print(result.stdout)

        # Collect screenshots
        pngs = sorted(tmp_dir.glob("slide_*.png"))
        print(f"Found {len(pngs)} screenshots")

        if not pngs:
            raise RuntimeError("No screenshots produced")

        # Assemble PPTX
        prs = Presentation()
        prs.slide_width = Emu(12192000)
        prs.slide_height = Emu(6858000)
        blank_layout = prs.slide_layouts[6]

        for img_path in pngs:
